import React, { useEffect, useState } from "react";
import axios from "axios";
import io from "socket.io-client";
import "./Schedule.css";
import { BACKEND_URL } from "../../config";

const socket = io(BACKEND_URL);

const STAGES = ["League", "Qualifier", "Semi Final", "Final"];

const Schedule = () => {
  const user = JSON.parse(localStorage.getItem("user"));
  const isAdmin = user?.role === "Admin";

  const eventId = localStorage.getItem("eventId"); // MUST EXIST
  const teams = JSON.parse(localStorage.getItem("teams")) || [];

  const [venue, setVenue] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [matches, setMatches] = useState([]);

  const fetchSchedule = async () => {
    if (!eventId) return;
    const res = await axios.get(
      `${BACKEND_URL}/api/schedule/${eventId}`
    );
    setMatches(res.data);
  };

  useEffect(() => {
    fetchSchedule();

    socket.on("schedule:refresh", (id) => {
      if (id === eventId) fetchSchedule();
    });

    return () => socket.off("schedule:refresh");
  }, []);

  const generateSchedule = async () => {
    if (!isAdmin) return alert("Admin only");
    if (!teams.length) return alert("No teams found");
    if (!startDate || !endDate) return alert("Select date range");
    if (!venue) return alert("Enter venue");

    await axios.post(`${BACKEND_URL}/api/schedule/generate`, {
      eventId,
      teams,
      venue,
      startDate,
      endDate
    });

    socket.emit("schedule:update", eventId);
  };

  return (
    <div className="schedule-container">
      <h1>🏆 Tournament Schedule</h1>

      {isAdmin && (
        <div className="card">
          <input
            placeholder="Venue / Ground"
            value={venue}
            onChange={(e) => setVenue(e.target.value)}
          />
          <input
            type="date"
            onChange={(e) => setStartDate(e.target.value)}
          />
          <input
            type="date"
            onChange={(e) => setEndDate(e.target.value)}
          />
          <button onClick={generateSchedule}>
            Generate Schedule
          </button>
        </div>
      )}

      <table className="schedule-table">
        <thead>
          <tr>
            <th>Match</th>
            <th>Stage</th>
            <th>Venue</th>
            <th>Date</th>
            <th>Time Slot</th>
          </tr>
        </thead>
        <tbody>
          {matches.map((m, i) => (
            <tr
              key={i}
              className={`stage-${m.stage.replace(" ", "").toLowerCase()}`}
            >
              <td>{m.homeTeam?.teamName} vs {m.awayTeam?.teamName}</td>
              <td>{m.stage}</td>
              <td>{m.venue}</td>
              <td>{new Date(m.startTime).toDateString()}</td>
              <td>{m.timeSlot}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default Schedule;
